export const s12HomesciHi: Record<string, { stem: string; options: string[]; explanation: string }> = {
  "s12hm-b-001": { stem: "बेरी-बेरी, जो 'आर्द्र' रूप (शोथ और हृदय संबंधी लक्षणों सहित) या 'शुष्क' रूप (परिधीय तंत्रिका शोथ सहित) में हो सकता है, किसकी कमी से होता है?", options: ["थायमिन (विटामिन B₁)", "नियासिन", "राइबोफ्लेविन (विटामिन B₂)", "विटामिन B₁₂"], explanation: "थायमिन (थायमिन पायरोफॉस्फेट के रूप में) कार्बोहाइड्रेट उपापचय का सहएंजाइम है; इसकी कमी से बेरी-बेरी होता है। नियासिन की कमी से पेलाग्रा होता है।" },
  "s12hm-b-002": { stem: "रतौंधी और नेत्र की कंजंक्टाइवा पर बिटॉट के धब्बे किसकी कमी के प्रारंभिक लक्षण हैं?", options: ["विटामिन D", "विटामिन A", "विटामिन K", "विटामिन B₁₂"], explanation: "विटामिन A से रोडॉप्सिन (दृष्टि बैंगनी) बनता है जो मंद प्रकाश में देखने के लिए आवश्यक है; इसकी कमी से रतौंधी, बिटॉट के धब्बे और अंततः किरैटोमलेशिया होता है।" },
  "s12hm-b-003": { stem: "'3 D' (त्वचाशोथ, अतिसार और मनोभ्रंश) से पहचाना जाने वाला रोग, जो वहाँ सामान्य है जहाँ मक्का मुख्य अनाज है, किसकी कमी से होता है?", options: ["राइबोफ्लेविन", "पाइरिडॉक्सिन", "नियासिन", "फोलिक अम्ल"], explanation: "यह पेलाग्रा है, जो नियासिन की कमी से होता है। मक्के में उपलब्ध नियासिन और ट्रिप्टोफैन (जिससे शरीर नियासिन बना सकता है) दोनों कम होते हैं।" },
  "s12hm-b-004": { stem: "निम्नलिखित में से कौन शरीर में पूर्ण ऑक्सीकरण पर लगभग 9 kcal प्रति ग्राम ऊर्जा देता है?", options: ["कार्बोहाइड्रेट", "प्रोटीन", "ऐल्कोहॉल", "वसा"], explanation: "वसा लगभग 9 kcal/g देती है, जबकि कार्बोहाइड्रेट और प्रोटीन प्रत्येक लगभग 4 kcal/g तथा ऐल्कोहॉल लगभग 7 kcal/g देता है।" },
  "s12hm-b-005": { stem: "वयस्कों में घेंघा और माता में गंभीर कमी होने पर शिशु में क्रेटिनता किसकी कमी से होती है?", options: ["आयोडीन", "लौह", "जस्ता", "फ्लोरीन"], explanation: "आयोडीन थायरॉइड हॉर्मोन थायरॉक्सिन (T₄) और ट्राइआयोडोथायरोनिन (T₃) का आवश्यक घटक है; इसकी कमी से घेंघा और गर्भावस्था में शिशु में क्रेटिनता होती है।" },
  "s12hm-b-006": { stem: "एक कुपोषित दो वर्षीय बच्चे के पैरों में शोथ, चंद्राकार चेहरा, 'उखड़े पेंट' जैसे त्वचा घाव और विरल, बदरंग बाल हैं, जबकि कुछ अधस्त्वक वसा अभी भी बची है। सबसे संभावित स्थिति है:", options: ["मरास्मस", "क्वाशियोरकर", "रिकेट्स", "स्कर्वी"], explanation: "त्वचा और बालों के परिवर्तनों के साथ शोथ क्वाशियोरकर की पहचान है। मरास्मस में अधस्त्वक वसा के क्षय के साथ गंभीर क्षीणता होती है पर शोथ नहीं होता।" },
  "s12hm-b-007": { stem: "दूध के पाश्चुरीकरण की उच्च ताप अल्प समय (HTST) विधि में दूध को लगभग कितना गर्म किया जाता है?", options: ["63°C पर 30 मिनट", "100°C पर 5 मिनट", "72°C पर 15 सेकंड", "135°C पर 2 सेकंड"], explanation: "HTST पाश्चुरीकरण में लगभग 72°C पर 15 सेकंड गर्म कर तुरंत ठंडा किया जाता है। 63°C पर 30 मिनट होल्डर (LTH) विधि है और लगभग 135°C पर कुछ सेकंड UHT उपचार है।" },
  "s12hm-b-008": { stem: "खेसारी दाल (Lathyrus sativus) से मिलावटी अरहर दाल के लंबे समय तक सेवन से कौन-सा रोग हो सकता है?", options: ["महामारी जलोदर (एपिडेमिक ड्रॉप्सी)", "फ्लोरोसिस", "बेरी-बेरी", "लैथिरिज्म"], explanation: "खेसारी दाल में तंत्रिका-विष β-ODAP (BOAA) होता है, जो लैथिरिज्म अर्थात् निचले अंगों का अपंग करने वाला पक्षाघात उत्पन्न करता है। महामारी जलोदर सरसों तेल में आर्जीमोन तेल की मिलावट से होता है।" },
  "s12hm-b-009": { stem: "अधिक चीनी वाले जैम और जेली मुख्यतः इसलिए सुरक्षित रहते हैं क्योंकि चीनी:", options: ["उच्च परासरण दाब उत्पन्न करती है जो सूक्ष्मजीव कोशिकाओं से जल खींच लेता है", "बिना गर्म किए ही सभी सूक्ष्मजीवों को मार देती है", "उत्पाद का pH बढ़ा देती है", "पात्र से पूरी वायु निकाल देती है"], explanation: "चीनी की उच्च सांद्रता सूक्ष्मजीवों के लिए जल को अनुपलब्ध बना देती है; परासरण द्वारा उनकी कोशिकाएँ निर्जलित हो जाती हैं और उनकी वृद्धि रुक जाती है।" },
  "s12hm-b-010": { stem: "निम्नलिखित में विटामिन C का सबसे समृद्ध स्रोत है:", options: ["गाजर", "आँवला", "पालक", "केला"], explanation: "आँवला ऐस्कॉर्बिक अम्ल के सबसे समृद्ध प्राकृतिक स्रोतों में से है, जो पालक या केले से कहीं अधिक समृद्ध है। गाजर मुख्यतः β-कैरोटीन के लिए महत्त्वपूर्ण है।" },
  "s12hm-b-011": { stem: "आहार नियोजन में प्रयुक्त ICMR की पाँच खाद्य वर्ग प्रणाली में कौन-सा वर्ग सामान्य भारतीय आहार में अधिकांश ऊर्जा के साथ B-समूह विटामिन और रेशा भी देता है?", options: ["वसा और शर्करा", "फल और सब्जियाँ", "अनाज, दाने और उनके उत्पाद", "दूध और मांस उत्पाद"], explanation: "भारतीय आहार में अनाज और मोटे अनाज ऊर्जा के मुख्य स्रोत हैं और प्रोटीन, थायमिन, नियासिन तथा रेशा भी देते हैं। वसा और शर्करा ऊर्जा तो देते हैं पर लगभग कोई विटामिन या रेशा नहीं।" },
  "s12hm-b-012": { stem: "उच्च रक्तचाप के रोगी के उपचारात्मक आहार में सबसे महत्त्वपूर्ण आहार परिवर्तन किसका प्रतिबंध है?", options: ["प्रोटीन", "आहारीय रेशा", "पोटैशियम", "सोडियम"], explanation: "सोडियम (साधारण नमक) के प्रतिबंध से रक्तचाप घटता है। ऐसे आहार में रेशा और पोटैशियम-समृद्ध फल-सब्जियों को वस्तुतः प्रोत्साहित किया जाता है।" },
  "s12hm-b-013": { stem: "अनाज और दालों से अहीम लौह का अवशोषण किससे बढ़ता है?", options: ["उसी भोजन के साथ लिया गया विटामिन C", "भोजन के साथ ली गई चाय के टैनिन", "चोकर के फाइटेट", "कुछ पत्तेदार सब्जियों के ऑक्सलेट"], explanation: "ऐस्कॉर्बिक अम्ल फेरिक लौह को अधिक अवशोषणीय फेरस रूप में अपचयित करता है। टैनिन, फाइटेट और ऑक्सलेट लौह से बंध कर उसका अवशोषण घटाते हैं।" },
  "s12hm-p-001": { stem: "अभिकथन (A): खिचड़ी जैसे अनाज-दाल संयोजन की प्रोटीन गुणवत्ता दोनों में से किसी एक को अकेले खाने से बेहतर होती है। कारण (R): अनाज प्रोटीन में लाइसिन सीमित होता है, जबकि दाल प्रोटीन में मेथियोनीन जैसे सल्फर-युक्त ऐमीनो अम्ल सीमित होते हैं।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "दालें वह लाइसिन देती हैं जिसकी अनाज में कमी है और अनाज वह मेथियोनीन देते हैं जिसकी दालों में कमी है; यही पारस्परिक पूरकता प्रोटीन गुणवत्ता में सुधार की व्याख्या करती है।" },
  "s12hm-p-002": { stem: "एक महिला का भार 72 kg और लंबाई 1.60 m है। उसका बॉडी मास इंडेक्स (BMI) लगभग है:", options: ["22.5 kg/m²", "28.1 kg/m²", "45.0 kg/m²", "25.6 kg/m²"], explanation: "BMI = भार (kg)/लंबाई² (m²) = 72/(1.60)² = 72/2.56 ≈ 28.1 kg/m²। लंबाई के वर्ग के बजाय लंबाई से भाग देने पर 45.0 आता है।" },
  "s12hm-p-003": { stem: "एक नाश्ते में 20 g कार्बोहाइड्रेट, 5 g प्रोटीन और 10 g वसा है। शरीरक्रियात्मक ईंधन मानों के अनुसार इसका ऊर्जा मान है:", options: ["175 kcal", "215 kcal", "190 kcal", "140 kcal"], explanation: "ऊर्जा = (20 × 4) + (5 × 4) + (10 × 9) = 80 + 20 + 90 = 190 kcal।" },
  "s12hm-p-004": { stem: "विटामिनों (सूची I) का उनके रासायनिक नामों (सूची II) से मिलान कीजिए। सूची I: A. विटामिन B₂, B. विटामिन B₆, C. विटामिन B₁₂, D. विटामिन K। सूची II: 1. कोबालामिन, 2. फिलोक्विनोन, 3. राइबोफ्लेविन, 4. पाइरिडॉक्सिन।", options: ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-1, B-4, C-3, D-2", "A-3, B-4, C-1, D-2"], explanation: "B₂ राइबोफ्लेविन, B₆ पाइरिडॉक्सिन, B₁₂ कोबालामिन (इसमें कोबाल्ट होता है) और विटामिन K₁ फिलोक्विनोन है।" },
  "s12hm-p-005": { stem: "मधुमेह के आहार नियोजन में प्रयुक्त ग्लाइसेमिक सूचकांक (GI) के संबंध में निम्नलिखित में से कौन-सा कथन सही है?", options: ["घुलनशील रेशा-समृद्ध खाद्यों का GI सामान्यतः कम होता है", "GI खाद्य के कार्बोहाइड्रेट अंश की परवाह किए बिना प्रति 100 g व्यक्त किया जाता है", "शुद्ध ग्लूकोज का GI 50 माना जाता है", "कम GI वाला खाद्य उच्च GI वाले खाद्य से अधिक तेज़ी से रक्त ग्लूकोज बढ़ाता है"], explanation: "घुलनशील रेशा आमाशय के रिक्त होने और ग्लूकोज अवशोषण को धीमा कर GI घटाता है। GI समान उपलब्ध कार्बोहाइड्रेट वाले भागों की तुलना ग्लूकोज (GI = 100) से करता है, और कम GI वाले खाद्य रक्त ग्लूकोज धीरे बढ़ाते हैं।" },
  "s12hm-p-006": { stem: "खाद्य सुरक्षा और मानक अधिनियम, जिसने भारत के खाद्य कानूनों को समेकित किया और खाद्य अपमिश्रण निवारण अधिनियम, 1954 का स्थान लिया, कब अधिनियमित हुआ?", options: ["1954", "2006", "1986", "2011"], explanation: "खाद्य सुरक्षा और मानक अधिनियम 2006 में अधिनियमित हुआ और इसके अंतर्गत FSSAI की स्थापना हुई। इसके विनियम 2011 में लागू हुए, जो एक भ्रामक परंतु गलत विकल्प है।" },
  "s12hm-p-007": { stem: "कमरे के तापमान पर रखी गई, घर पर अनुचित ढंग से डिब्बाबंद कम-अम्लीय सब्जियाँ किस जीवाणु द्वारा होने वाले संभावित घातक तंत्रिका-पक्षाघाती खाद्य विषाक्तन से सर्वाधिक जुड़ी हैं?", options: ["स्टैफिलोकोकस ऑरियस", "बैसिलस सेरियस", "क्लॉस्ट्रिडियम बोटुलिनम", "साल्मोनेला"], explanation: "C. botulinum एक अवायवीय बीजाणुधारी जीवाणु है जो बंद, कम-अम्लीय खाद्यों में बढ़ता है और तंत्रिका-विष बना कर बोटुलिज्म उत्पन्न करता है। B. cereus सामान्यतः दोबारा गर्म किए गए चावल से जुड़ा है।" },
  "s12hm-p-008": { stem: "सीलिएक रोग के एक रोगी को ग्लूटेन-मुक्त आहार दिया गया है। निम्नलिखित में से किस खाद्य से बचना आवश्यक है?", options: ["चावल", "मक्का", "आलू", "जौ"], explanation: "ग्लूटेन बनाने वाले प्रोटीन गेहूँ, जौ और राई में होते हैं, अतः जौ वर्जित है। चावल, मक्का और आलू ग्लूटेन-मुक्त हैं।" },
  "s12hm-p-009": { stem: "गठिया (गाउट) के आहार में अंग-मांस जैसे प्यूरीन-समृद्ध खाद्य सीमित किए जाते हैं क्योंकि शरीर में प्यूरीन का उपापचय होकर बनता है:", options: ["यूरिक अम्ल", "यूरिया", "अमोनिया", "क्रिएटिनिन"], explanation: "मनुष्य में प्यूरीन विघटन का अंतिम उत्पाद यूरिक अम्ल है; रक्त में इसकी वृद्धि से जोड़ों में यूरेट क्रिस्टल जमा होते हैं। यूरिया ऐमीनो अम्ल नाइट्रोजन का अंतिम उत्पाद है।" },
  "s12hm-p-010": { stem: "विटामिन D के संबंध में कथनों पर विचार कीजिए: I. यह पराबैंगनी-B प्रकाश के संपर्क में त्वचा में 7-डीहाइड्रोकोलेस्टेरॉल से संश्लेषित होता है। II. इसका सक्रिय हॉर्मोनी रूप 1,25-डाइहाइड्रॉक्सीकोलेकैल्सिफेरॉल (कैल्सिट्रिऑल) अंततः वृक्क में बनता है। III. वयस्कों में इसकी कमी से रिकेट्स होता है। कौन-सा/से सही है/हैं?", options: ["केवल I", "केवल I और II", "केवल II और III", "I, II और III"], explanation: "I और II सही हैं। विटामिन D की कमी से बच्चों में रिकेट्स पर वयस्कों में ऑस्टियोमलेशिया होता है, अतः III गलत है।" },
  "s12hm-p-011": { stem: "किसी पोषक तत्व की अनुशंसित आहारीय मात्रा (RDA) परंपरागत रूप से किस प्रकार निर्धारित की जाती है?", options: ["जनसंख्या की औसत आवश्यकता (EAR)", "सहनीय ऊपरी सेवन सीमा", "EAR में दो मानक विचलन जोड़कर, जो लगभग 97.5% स्वस्थ व्यक्तियों को आवृत करती है", "वह न्यूनतम सेवन जो आधी जनसंख्या में कमी के लक्षण रोकता है"], explanation: "RDA = EAR + 2 SD, अतः यह समूह के लगभग सभी (लगभग 97.5%) स्वस्थ लोगों की आवश्यकता पूरी करती है। EAR केवल आधी जनसंख्या की आवश्यकता पूरी करती है।" },
  "s12hm-p-012": { stem: "कमी और रक्ताल्पता के प्रकार का कौन-सा युग्म सही सुमेलित है?", options: ["लौह की कमी : मेगालोब्लास्टिक रक्ताल्पता", "विटामिन B₁₂ की कमी : माइक्रोसाइटिक हाइपोक्रोमिक रक्ताल्पता", "विटामिन C की कमी : प्रणाशी (पर्निशियस) रक्ताल्पता", "फोलिक अम्ल की कमी : मेगालोब्लास्टिक रक्ताल्पता"], explanation: "फोलेट (और B₁₂) की कमी DNA संश्लेषण बाधित करती है जिससे बड़ी अपरिपक्व लाल कोशिकाएँ बनती हैं (मेगालोब्लास्टिक रक्ताल्पता)। लौह की कमी से माइक्रोसाइटिक हाइपोक्रोमिक रक्ताल्पता होती है, और प्रणाशी रक्ताल्पता B₁₂ अवशोषण हेतु आंतरिक कारक की कमी से होती है।" },
  "s12hm-b-014": { stem: "पियाजे के अनुसार वस्तु स्थायित्व (यह समझ कि आँखों से ओझल वस्तुएँ भी अस्तित्व में रहती हैं) किस अवस्था में विकसित होता है?", options: ["पूर्व-संक्रियात्मक अवस्था", "संवेदी-गामक अवस्था", "मूर्त संक्रियात्मक अवस्था", "औपचारिक संक्रियात्मक अवस्था"], explanation: "वस्तु स्थायित्व संवेदी-गामक अवस्था (जन्म से लगभग 2 वर्ष) की प्रमुख उपलब्धि है।" },
  "s12hm-b-015": { stem: "एरिक्सन के मनोसामाजिक सिद्धांत में किशोरावस्था का केंद्रीय संकट है:", options: ["विश्वास बनाम अविश्वास", "परिश्रम बनाम हीनता", "पहचान बनाम भूमिका भ्रम", "सत्यनिष्ठा बनाम निराशा"], explanation: "किशोर स्वयं की सुसंगत पहचान गढ़ने का प्रयास करते हैं (पहचान बनाम भूमिका भ्रम)। परिश्रम बनाम हीनता विद्यालयी वर्षों का और सत्यनिष्ठा बनाम निराशा वृद्धावस्था का संकट है।" },
  "s12hm-b-016": { stem: "एक स्वस्थ पूर्णकालिक शिशु का जन्म भार लगभग किस आयु तक तिगुना हो जाता है?", options: ["6 माह", "2 वर्ष", "3 वर्ष", "1 वर्ष"], explanation: "जन्म भार लगभग 5 माह में दुगुना और लगभग 1 वर्ष में तिगुना हो जाता है, जो शैशवावस्था की अत्यंत तीव्र वृद्धि को दर्शाता है।" },
  "s12hm-b-017": { stem: "किशोरावस्था की वृद्धि-उछाल सामान्यतः पहले किसमें आरंभ होती है?", options: ["लड़कियों में, लगभग दो वर्ष पहले", "लड़कों में, लगभग दो वर्ष पहले", "दोनों लिंगों में ठीक एक ही आयु पर", "किसी में नहीं, क्योंकि पूरी किशोरावस्था में वृद्धि एकसमान रहती है"], explanation: "लड़कियाँ प्रायः लड़कों से लगभग दो वर्ष पहले यौवनारंभ और वृद्धि-उछाल में प्रवेश करती हैं, इसीलिए आरंभिक किशोरावस्था में कई लड़कियाँ लड़कों से लंबी होती हैं।" },
  "s12hm-b-018": { stem: "एक ही गृहस्थी में रहने वाले विवाहित दंपती और उनके अविवाहित बच्चों से बना परिवार कहलाता है:", options: ["संयुक्त परिवार", "एकल (नाभिकीय) परिवार", "विस्तारित परिवार", "मिश्रित परिवार"], explanation: "एकल परिवार में दो पीढ़ियाँ होती हैं: माता-पिता और उनके अविवाहित बच्चे। संयुक्त परिवार में कई संबंधित एकल इकाइयाँ, प्रायः तीन पीढ़ियाँ, होती हैं।" },
  "s12hm-b-019": { stem: "भारत की राष्ट्रीय प्रारंभिक बाल्यावस्था देखभाल और शिक्षा (ECCE) नीति, 2013 किस आयु वर्ग के बच्चों को आवृत करती है?", options: ["0–3 वर्ष", "3–8 वर्ष", "0–6 वर्ष", "6–14 वर्ष"], explanation: "राष्ट्रीय ECCE नीति जन्म से छह वर्ष तक के सभी बच्चों को आवृत करती है। 6–14 आयु वर्ग शिक्षा का अधिकार अधिनियम के अंतर्गत आता है।" },
  "s12hm-b-020": { stem: "बौद्धिक अक्षमता का एक सामान्य आनुवंशिक कारण डाउन सिंड्रोम प्रायः किसके कारण होता है?", options: ["ट्राइसोमी 18", "मोनोसोमी X", "ट्राइसोमी 13", "ट्राइसोमी 21"], explanation: "डाउन सिंड्रोम प्रायः गुणसूत्र 21 की एक अतिरिक्त प्रति से होता है। ट्राइसोमी 18 एडवर्ड्स सिंड्रोम, ट्राइसोमी 13 पटाउ सिंड्रोम और मोनोसोमी X टर्नर सिंड्रोम है।" },
  "s12hm-b-021": { stem: "भारत की राष्ट्रीय वृद्धजन नीति (1999) के अंतर्गत 'वरिष्ठ नागरिक' या वृद्ध व्यक्ति वह है जिसकी आयु है:", options: ["60 वर्ष और अधिक", "50 वर्ष और अधिक", "55 वर्ष और अधिक", "70 वर्ष और अधिक"], explanation: "1999 की नीति तथा बाद में माता-पिता और वरिष्ठ नागरिकों का भरण-पोषण तथा कल्याण अधिनियम, 2007 वृद्ध व्यक्तियों को 60 वर्ष और अधिक आयु वाले के रूप में परिभाषित करते हैं।" },
  "s12hm-b-022": { stem: "यह सिद्धांत कि विकास सिर से पैर की ओर होता है, जिससे शिशु पैरों से पहले सिर पर नियंत्रण पाता है, कहलाता है:", options: ["निकट-दूर (प्रॉक्सिमोडिस्टल) सिद्धांत", "मस्तकाधोमुखी (सिफैलोकॉडल) सिद्धांत", "सामान्य से विशिष्ट सिद्धांत", "केंद्रापसारी सिद्धांत"], explanation: "सिफैलोकॉडल का अर्थ है सिर से पूँछ की ओर। प्रॉक्सिमोडिस्टल विकास शरीर के केंद्र से बाहर की ओर अंगों के सिरों तक होता है।" },
  "s12hm-b-023": { stem: "'निकटस्थ विकास क्षेत्र' की अवधारणा, अर्थात् बच्चा अकेले जो कर सकता है और कुशल सहायता से जो कर सकता है उसके बीच का अंतर, किसने दी?", options: ["जीन पियाजे", "एरिक एरिक्सन", "लेव वाइगोत्स्की", "सिगमंड फ्रायड"], explanation: "वाइगोत्स्की का सामाजिक-सांस्कृतिक सिद्धांत निकटस्थ विकास क्षेत्र के भीतर निर्देशित अंतःक्रिया (पाड़ या स्कैफोल्डिंग) द्वारा अधिगम पर बल देता है।" },
  "s12hm-p-013": { stem: "एक बच्चा समझता है कि छोटे, चौड़े गिलास से लंबे, पतले गिलास में डालने पर पानी की मात्रा वही रहती है, पर वह अभी पूर्णतः काल्पनिक प्रतिज्ञप्तियों पर व्यवस्थित तर्क नहीं कर पाता। बच्चा पियाजे की किस अवस्था में है?", options: ["संवेदी-गामक अवस्था", "पूर्व-संक्रियात्मक अवस्था", "औपचारिक संक्रियात्मक अवस्था", "मूर्त संक्रियात्मक अवस्था"], explanation: "संरक्षण की समझ मूर्त संक्रियात्मक अवस्था (लगभग 7–11 वर्ष) में आती है, जबकि अमूर्त परिकल्पनात्मक-निगमनात्मक तर्क केवल औपचारिक संक्रियात्मक अवस्था में प्रकट होता है।" },
  "s12hm-p-014": { stem: "एरिक्सन की अवस्थाओं (सूची I) का जीवन-कालों (सूची II) से मिलान कीजिए। सूची I: A. विश्वास बनाम अविश्वास, B. स्वायत्तता बनाम लज्जा और संदेह, C. पहल बनाम अपराधबोध, D. परिश्रम बनाम हीनता। सूची II: 1. विद्यालयी आयु, 2. शैशवावस्था, 3. पूर्व-विद्यालयी (खेल) आयु, 4. टॉडलर अवस्था (प्रारंभिक बाल्यावस्था)।", options: ["A-2, B-4, C-3, D-1", "A-4, B-2, C-3, D-1", "A-2, B-3, C-4, D-1", "A-1, B-4, C-3, D-2"], explanation: "विश्वास बनाम अविश्वास शैशवावस्था, स्वायत्तता बनाम लज्जा और संदेह टॉडलर अवस्था (लगभग 1–3 वर्ष), पहल बनाम अपराधबोध पूर्व-विद्यालयी वर्ष और परिश्रम बनाम हीनता विद्यालयी आयु है।" },
  "s12hm-p-015": { stem: "एन्सवर्थ की 'स्ट्रेंज सिचुएशन' में एक शिशु माँ के जाने पर थोड़ा ही व्यथित होता है और लौटने पर उसे सक्रिय रूप से अनदेखा करता है या मुँह फेर लेता है। शिशु का आसक्ति प्रकार है:", options: ["सुरक्षित", "असुरक्षित-परिहारी", "असुरक्षित-प्रतिरोधी (उभयभावी)", "असंगठित"], explanation: "पुनर्मिलन पर माँ से बचना असुरक्षित-परिहारी आसक्ति की पहचान है। प्रतिरोधी शिशु बहुत व्यथित होते हैं और पुनर्मिलन पर संपर्क चाहते भी हैं और उसका विरोध भी करते हैं।" },
  "s12hm-p-016": { stem: "बॉमरिंड के वर्गीकरण में उच्च स्नेह और प्रतिक्रियाशीलता को दृढ़ परंतु तर्कसंगत नियंत्रण के साथ जोड़ने वाली पालन-पोषण शैली है:", options: ["सत्तावादी (ऑथोरिटेरियन)", "अनुज्ञात्मक (परमिसिव)", "आधिकारिक (ऑथोरिटेटिव)", "उदासीन (उपेक्षापूर्ण)"], explanation: "आधिकारिक माता-पिता माँग करने वाले और प्रतिक्रियाशील दोनों होते हैं तथा नियमों की व्याख्या करते हैं। सत्तावादी माता-पिता माँग तो करते हैं पर स्नेह कम देते हैं; अनुज्ञात्मक माता-पिता स्नेही होते हैं पर सीमाएँ कम तय करते हैं।" },
  "s12hm-p-017": { stem: "दिव्यांगजन अधिकार अधिनियम, 2016 के अंतर्गत मान्य विनिर्दिष्ट दिव्यांगताओं की संख्या है:", options: ["7", "14", "25", "21"], explanation: "2016 के अधिनियम ने सूची को नि:शक्त व्यक्ति अधिनियम, 1995 के 7 से बढ़ाकर 21 विनिर्दिष्ट दिव्यांगताएँ कर दिया।" },
  "s12hm-p-018": { stem: "एवलिन डुवाल का पारिवारिक जीवन-चक्र मॉडल, जो निःसंतान विवाहित दंपती से वृद्ध परिवार तक चलता है, चक्र को कितनी अवस्थाओं में बाँटता है?", options: ["आठ", "पाँच", "छह", "दस"], explanation: "डुवाल ने आठ अवस्थाएँ बताईं, प्रत्येक के अपने विकासात्मक कार्य हैं, आरंभिक (विवाहित दंपती) अवस्था से वृद्ध परिवार अवस्था तक।" },
  "s12hm-p-019": { stem: "अभिकथन (A): जो बच्चा मुख्यतः दंड से बचने के लिए नियमों का पालन करता है, वह कोलबर्ग के पूर्व-परंपरागत स्तर पर तर्क कर रहा है। कारण (R): परंपरागत स्तर पर नैतिक निर्णय स्वयं चुने गए सार्वभौमिक नैतिक सिद्धांतों पर आधारित होता है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "दंड और आज्ञापालन अभिमुखता पूर्व-परंपरागत है, अतः A सत्य है। सार्वभौमिक नैतिक सिद्धांत उत्तर-परंपरागत स्तर के हैं; परंपरागत स्तर सामाजिक स्वीकृति और कानून-व्यवस्था पर आधारित है, अतः R असत्य है।" },
  "s12hm-p-020": { stem: "वृद्धावस्था का वह सिद्धांत जो मानता है कि वृद्ध व्यक्ति और समाज धीरे-धीरे परस्पर एक-दूसरे से अलग हो जाते हैं और यह एक सामान्य प्रक्रिया है, कहलाता है:", options: ["सक्रियता सिद्धांत", "निरंतरता सिद्धांत", "विमुक्ति (डिसएंगेजमेंट) सिद्धांत", "घिसाव-टूट सिद्धांत"], explanation: "विमुक्ति सिद्धांत (कमिंग और हेनरी) पारस्परिक अलगाव का प्रस्ताव करता है। सक्रियता सिद्धांत इसके विपरीत कहता है कि सक्रिय बने रहना सफल वृद्धावस्था में सहायक है; घिसाव-टूट एक जैविक सिद्धांत है।" },
  "s12hm-p-021": { stem: "ब्रॉनफेनब्रेनर के पारिस्थितिक तंत्र सिद्धांत में बच्चे के माता-पिता और उसके शिक्षकों के बीच का संबंध किसका भाग है?", options: ["सूक्ष्म तंत्र (माइक्रोसिस्टम)", "बाह्य तंत्र (एक्सोसिस्टम)", "वृहत् तंत्र (मैक्रोसिस्टम)", "मध्य तंत्र (मेसोसिस्टम)"], explanation: "मध्य तंत्र बच्चे के सूक्ष्म तंत्रों, जैसे घर और विद्यालय, के बीच की कड़ियों से बनता है। प्रत्येक परिवेश अपने आप में एक सूक्ष्म तंत्र है।" },
  "s12hm-p-022": { stem: "एक किशोर मानता है, 'मेरे जैसा अनुभव कभी किसी ने नहीं किया, और मेरा कुछ बुरा नहीं हो सकता।' एल्किंड के किशोर आत्मकेंद्रिता के विवरण में यह किसका उदाहरण है?", options: ["व्यक्तिगत दंतकथा (पर्सनल फेबल)", "काल्पनिक दर्शक (इमैजिनरी ऑडियंस)", "पहचान पूर्व-बंधन (आइडेंटिटी फोरक्लोज़र)", "केंद्रीकरण (सेंट्रेशन)"], explanation: "व्यक्तिगत दंतकथा यह विश्वास है कि व्यक्ति के अनुभव अनोखे हैं और वह अजेय है। काल्पनिक दर्शक यह भावना है कि दूसरे लगातार उसे देख और परख रहे हैं।" },
  "s12hm-b-024": { stem: "निम्नलिखित में से कौन-सा प्राकृतिक प्रोटीन रेशा है?", options: ["कपास", "ऊन", "लिनन", "जूट"], explanation: "ऊन केराटिन प्रोटीन से बना प्राणिज रेशा है। कपास, लिनन और जूट वनस्पति (सेलुलोसीय) रेशे हैं।" },
  "s12hm-b-025": { stem: "दहन परीक्षण में एक रेशा पीली लौ के साथ तेज़ी से जलता है, जलते कागज़ जैसी गंध देता है और थोड़ी मुलायम धूसर राख छोड़ता है। यह रेशा संभवतः है:", options: ["ऊन", "रेशम", "कपास", "पॉलिएस्टर"], explanation: "कपास जैसे सेलुलोसीय रेशे जलते कागज़ की गंध देते हैं और मुलायम धूसर राख छोड़ते हैं। ऊन और रेशम जलते बालों की गंध देते हैं और पॉलिएस्टर पिघलकर कठोर मनका बनाता है।" },
  "s12hm-b-026": { stem: "डेनिम, जिसकी सतह पर स्पष्ट तिरछी रेखाएँ दिखती हैं, सामान्यतः किस बुनाई में बुना जाता है?", options: ["सादी बुनाई", "साटिन बुनाई", "लीनो बुनाई", "ट्विल बुनाई"], explanation: "ट्विल बुनाई से तिरछी धारियाँ और डेनिम या गैबर्डीन जैसा मज़बूत, टिकाऊ वस्त्र बनता है।" },
  "s12hm-b-027": { stem: "शहतूती रेशम किसके लार्वा से प्राप्त होता है?", options: ["बॉम्बिक्स मोरी", "एंथेरिया मायलिट्टा", "सामिया रिसिनी", "एंथेरिया असामेन्सिस"], explanation: "बॉम्बिक्स मोरी शहतूत की पत्तियाँ खाता है। एंथेरिया मायलिट्टा से तसर, सामिया रिसिनी से एरी और एंथेरिया असामेन्सिस से मूगा रेशम मिलता है।" },
  "s12hm-b-028": { stem: "मर्सरीकरण, जो कपास की चमक, मज़बूती और रंग-ग्राह्यता बढ़ाता है, में सूत या वस्त्र को तनाव में रखकर किससे उपचारित किया जाता है?", options: ["सल्फ्यूरिक अम्ल", "सोडियम हाइड्रॉक्साइड (कास्टिक सोडा)", "हाइड्रोजन परॉक्साइड", "सोडियम क्लोराइड"], explanation: "सांद्र कास्टिक सोडा कपास के रेशों को फुलाकर अधिक गोल और चमकीला बना देता है। हाइड्रोजन परॉक्साइड विरंजन के लिए प्रयुक्त होता है।" },
  "s12hm-b-029": { stem: "अंतरराष्ट्रीय देखभाल-लेबल प्रणाली में त्रिभुज चिह्न किसके बारे में निर्देश देता है?", options: ["इस्त्री करना", "ड्राई क्लीनिंग", "विरंजन (ब्लीचिंग)", "टम्बल ड्राइंग"], explanation: "त्रिभुज विरंजन को दर्शाता है। इस्त्री को इस्त्री के चिह्न से, ड्राई क्लीनिंग को वृत्त से और टम्बल ड्राइंग को वर्ग के भीतर वृत्त से दिखाया जाता है।" },
  "s12hm-b-030": { stem: "पटोला, एक दोहरी इकत रेशमी साड़ी जिसमें बुनाई से पहले ताना और बाना दोनों प्रतिरोध-रंजित होते हैं, परंपरागत रूप से किससे जुड़ी है?", options: ["पश्चिम बंगाल", "तमिलनाडु", "असम", "गुजरात"], explanation: "पटोला साड़ियाँ गुजरात के पाटन में बुनी जाती हैं और सर्वश्रेष्ठ दोहरी इकत वस्त्रों में गिनी जाती हैं।" },
  "s12hm-b-031": { stem: "गुजरात और राजस्थान का बांधनी किस पारंपरिक तकनीक का उदाहरण है?", options: ["कपड़े के छोटे भागों को बाँधकर प्रतिरोध रंगाई", "नक्काशीदार लकड़ी के ठप्पों से छपाई", "शीशों के साथ कढ़ाई", "सोने के धागों से ज़री (ब्रोकेड) बुनाई"], explanation: "बांधनी में रंगाई से पहले कपड़े के छोटे-छोटे बिंदुओं को धागे से कसकर बाँधा जाता है, जिससे बँधे भाग रंग नहीं पकड़ते और बिंदुदार आकृतियाँ बनती हैं।" },
  "s12hm-b-032": { stem: "एकमात्र प्राकृतिक रेशा जो लंबे निरंतर तंतु (फिलामेंट) के रूप में मिलता है:", options: ["कपास", "रेशम", "ऊन", "फ्लैक्स (अलसी)"], explanation: "रेशम कोकून से सैकड़ों मीटर लंबे निरंतर तंतु के रूप में खोला जाता है। कपास, ऊन और फ्लैक्स स्टेपल (छोटे) रेशे हैं।" },
  "s12hm-b-033": { stem: "दो या अधिक एकल सूतों को एक साथ ऐंठकर बनाए गए सूत कहलाते हैं:", options: ["नवीनता (नॉवेल्टी) सूत", "एकतंतु (मोनोफिलामेंट) सूत", "प्लाई सूत", "टेक्सचर्ड सूत"], explanation: "एकल सूतों को एक साथ ऐंठने से प्लाई (जैसे दो-प्लाई) सूत बनते हैं, जो अधिक मज़बूत और एकसमान होते हैं। मोनोफिलामेंट एक अकेला तंतु होता है।" },
  "s12hm-p-023": { stem: "मानक वायुमंडलीय परिस्थितियों में निम्नलिखित में से किस रेशे की नमी पुनर्प्राप्ति (मॉइस्चर रीगेन) सबसे अधिक है?", options: ["पॉलिएस्टर", "नायलॉन", "कपास", "ऊन"], explanation: "ऊन अत्यधिक आर्द्रताग्राही है और इसकी नमी पुनर्प्राप्ति लगभग 13–16% है, जो कपास से अधिक है; पॉलिएस्टर बहुत कम नमी सोखता है, इसीलिए गर्मी में चिपचिपा लगता है।" },
  "s12hm-p-024": { stem: "पारंपरिक वस्त्रों (सूची I) का उनके राज्यों (सूची II) से मिलान कीजिए। सूची I: A. चंदेरी, B. पोचमपल्ली इकत, C. कांजीवरम रेशम, D. बालूचरी। सूची II: 1. तेलंगाना, 2. पश्चिम बंगाल, 3. मध्य प्रदेश, 4. तमिलनाडु।", options: ["A-3, B-1, C-4, D-2", "A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-4, B-1, C-3, D-2"], explanation: "चंदेरी मध्य प्रदेश का, पोचमपल्ली इकत तेलंगाना का, कांजीवरम रेशम तमिलनाडु का और बालूचरी साड़ियाँ पश्चिम बंगाल के बिष्णुपुर की हैं।" },
  "s12hm-p-025": { stem: "वह बुनाई जिसमें एक समूह के सूत दूसरे समूह के चार या अधिक सूतों के ऊपर तैरते हैं और अंतर्ग्रथन इस प्रकार बिखरे होते हैं कि कोई तिरछी रेखा नहीं दिखती, जिससे चिकनी, चमकीली परंतु आसानी से उलझने वाली सतह बनती है:", options: ["ट्विल बुनाई", "साटिन बुनाई", "बास्केट बुनाई", "सादी बुनाई"], explanation: "लंबे फ्लोट और बिखरे अंतर्ग्रथन साटिन बुनाई की विशेषता हैं, जिससे चमक तो आती है पर घर्षण और उलझन के प्रति प्रतिरोध कम होता है। ट्विल के अंतर्ग्रथन दिखाई देने वाली तिरछी रेखाएँ बनाते हैं।" },
  "s12hm-p-026": { stem: "कौन-सी परिसज्जा नियंत्रित संपीडन द्वारा सूती वस्त्र को यांत्रिक रूप से पहले ही सिकोड़ देती है ताकि बाद में धोने पर वह बहुत कम सिकुड़े?", options: ["मर्सरीकरण", "कैलेंडरिंग", "सैनफोराइज़ेशन", "सिंजिंग"], explanation: "सैनफोराइज़ेशन एक संपीडी सिकुड़न प्रक्रिया है जो अधिकांश अवशिष्ट सिकुड़न हटा देती है। कैलेंडरिंग में वस्त्र को बेलनों के बीच दबाकर चिकनापन या चमक दी जाती है, सिकुड़न-प्रतिरोध नहीं।" },
  "s12hm-p-027": { stem: "पॉलिएस्टर की रंगाई के लिए कौन-सा रंजक वर्ग सबसे उपयुक्त है?", options: ["प्रत्यक्ष रंजक", "अम्लीय रंजक", "क्षारीय रंजक", "परिक्षेपी (डिस्पर्स) रंजक"], explanation: "पॉलिएस्टर जलविरागी है और इसमें आयनिक रंजक स्थल नहीं होते, अतः इसे अल्प-विलेय परिक्षेपी रंजकों से, प्रायः उच्च ताप पर, रंगा जाता है। अम्लीय रंजक ऊन, रेशम और नायलॉन के लिए तथा प्रत्यक्ष रंजक कपास के लिए उपयुक्त हैं।" },
  "s12hm-p-028": { stem: "किस छपाई तकनीक में वस्त्र को पहले पूरा रंगा जाता है और फिर एक रासायनिक लेप छापकर डिज़ाइन वाले भागों से रंग हटाया जाता है?", options: ["विसर्जन (डिस्चार्ज) छपाई", "प्रतिरोध (रेज़िस्ट) छपाई", "प्रत्यक्ष ठप्पा छपाई", "बेलन (रोलर) छपाई"], explanation: "डिस्चार्ज छपाई डिज़ाइन में पृष्ठभूमि का रंग हटा देती है। प्रतिरोध छपाई में रंगाई से पहले डिज़ाइन को सुरक्षित किया जाता है ताकि रंग वहाँ न पहुँचे।" },
  "s12hm-p-029": { stem: "कथनों पर विचार कीजिए: I. नायलॉन व्यावसायिक रूप से उत्पादित पहला पूर्णतः संश्लेषित रेशा था। II. पॉलिएस्टर तापसुघट्य है, अतः इसमें चुन्नटें स्थायी रूप से ताप-स्थिर की जा सकती हैं। III. ऐक्रिलिक एक पुनर्जनित सेलुलोसीय रेशा है। कौन-सा/से सही है/हैं?", options: ["केवल I", "केवल I और II", "केवल II और III", "I, II और III"], explanation: "I और II सही हैं। ऐक्रिलिक ऐक्रिलोनाइट्राइल से बना संश्लेषित रेशा है, पुनर्जनित सेलुलोस नहीं, अतः III गलत है।" },
  "s12hm-p-030": { stem: "अभिकथन (A): विस्कोस रेयॉन मानव-निर्मित रेशा है, फिर भी इसे प्रायः अर्ध-संश्लेषित कहा जाता है। कारण (R): यह पेट्रो-रसायनों के बहुलकीकरण से नहीं, बल्कि लकड़ी की लुगदी जैसे स्रोतों के प्राकृतिक सेलुलोस के पुनर्जनन से बनता है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "विस्कोस का निर्माण होता है, पर इसका कच्चा माल प्राकृतिक सेलुलोस है जिसे घोलकर पुनर्जनित किया जाता है; ठीक इसी कारण इसे अर्ध-संश्लेषित या पुनर्जनित कहते हैं।" },
  "s12hm-p-031": { stem: "किसी सूत की 2000 m लंबाई का भार 40 g है। टेक्स (प्रति 1000 m ग्राम) में इसका रैखिक घनत्व है:", options: ["40 tex", "80 tex", "50 tex", "20 tex"], explanation: "टेक्स = 1000 m का ग्राम में द्रव्यमान = 40 g/2 = 20 tex। टेक्स एक प्रत्यक्ष प्रणाली है: अधिक मान का अर्थ है भारी (मोटा) सूत।" },
  "s12hm-p-032": { stem: "वह प्रारंभिक प्रक्रिया जिसमें वस्त्र को लौ या गर्म प्लेटों के ऊपर से तेज़ी से गुज़ारकर उभरे रेशों के सिरे जला दिए जाते हैं, ताकि सतह चिकनी हो जाए:", options: ["सिंजिंग", "साइज़िंग", "स्कॉरिंग", "डीसाइज़िंग"], explanation: "सिंजिंग सतह के रोएँ हटाता है। डीसाइज़िंग ताने के सूतों पर लगाया गया माँड़ हटाता है और स्कॉरिंग प्राकृतिक मोम तथा अशुद्धियाँ हटाता है।" },
  "s12hm-b-034": { stem: "पारिवारिक संसाधनों के वर्गीकरण में निम्नलिखित में से कौन-सा मानवीय संसाधन है?", options: ["धन", "ज्ञान और कौशल", "भौतिक वस्तुएँ", "सामुदायिक उद्यान"], explanation: "ज्ञान, कौशल, रुचियाँ और ऊर्जा मानवीय संसाधन हैं जो व्यक्तियों में निहित होते हैं। धन और भौतिक वस्तुएँ अमानवीय संसाधन हैं, और उद्यान सामुदायिक संसाधन हैं।" },
  "s12hm-b-035": { stem: "प्रबंधन प्रक्रिया के चरणों का सही क्रम है:", options: ["मूल्यांकन, नियोजन, संगठन, कार्यान्वयन", "संगठन, नियोजन, मूल्यांकन, कार्यान्वयन", "नियोजन, संगठन, कार्यान्वयन और नियंत्रण, मूल्यांकन", "कार्यान्वयन, मूल्यांकन, नियोजन, संगठन"], explanation: "प्रबंधन नियोजन से आरंभ होता है, फिर संगठन, फिर योजना का कार्यान्वयन करते हुए उसकी प्रगति का नियंत्रण, और अंत में मूल्यांकन।" },
  "s12hm-b-036": { stem: "उपभोक्ता संरक्षण अधिनियम, 1986 का स्थान किस वर्ष अधिनियमित नए उपभोक्ता संरक्षण अधिनियम ने लिया?", options: ["2005", "2012", "2023", "2019"], explanation: "उपभोक्ता संरक्षण अधिनियम, 2019 ने 1986 के अधिनियम का स्थान लिया और केंद्रीय उपभोक्ता संरक्षण प्राधिकरण तथा ई-कॉमर्स और उत्पाद दायित्व संबंधी प्रावधान जोड़े।" },
  "s12hm-b-037": { stem: "घी या शहद खरीदने वाले उपभोक्ता को कृषि और संबद्ध उत्पादों के लिए निर्धारित कौन-सा गुणवत्ता प्रमाणन चिह्न देखना चाहिए?", options: ["एगमार्क", "ISI चिह्न", "BIS हॉलमार्क", "इकोमार्क"], explanation: "एगमार्क कृषि उत्पादों को प्रमाणित करता है। ISI चिह्न औद्योगिक उत्पादों के लिए, BIS हॉलमार्क सोने-चाँदी के आभूषणों के लिए और इकोमार्क पर्यावरण-हितैषी उत्पादों के लिए है।" },
  "s12hm-b-038": { stem: "घर में कार्य सरलीकरण का उद्देश्य है:", options: ["सभी घरेलू कार्यों को समाप्त करना", "न्यूनतम समय और ऊर्जा व्यय से निर्धारित परिणाम प्राप्त करना", "प्रत्येक कार्य के लिए श्रमिकों की संख्या बढ़ाना", "सभी हस्त-कार्यों को मशीनों से बदलना"], explanation: "कार्य सरलीकरण का अर्थ है किसी कार्य को सचेत रूप से सबसे सरल, शीघ्र और आसान ढंग से करना, जिससे समान या बेहतर परिणाम के लिए समय और ऊर्जा बचे।" },
  "s12hm-b-039": { stem: "मंडेल के 'परिवर्तन के वर्ग' (शारीरिक गतियों में, कार्यस्थल और उपकरणों में, उत्पादन क्रम में, तैयार उत्पाद में और कच्चे माल में परिवर्तन) किससे संबंधित हैं?", options: ["उपभोक्ता अधिकार", "संप्रेषण मॉडल", "कार्य सरलीकरण", "पारिवारिक जीवन-चक्र"], explanation: "मंडेल ने उन तरीकों का वर्गीकरण किया जिनसे किसी कार्य को सरल बनाने हेतु बदला जा सकता है; परिवर्तन के ये वर्ग कार्य सरलीकरण का मानक ढाँचा हैं।" },
  "s12hm-b-040": { stem: "श्रमदक्षता शास्त्र (एर्गोनॉमिक्स) को सबसे उचित रूप में किसका अध्ययन कहा जा सकता है?", options: ["पारिवारिक बजट बनाना", "खाद्य संरक्षण", "शिशु-पालन प्रथाएँ", "कार्य, उपकरणों और कार्यस्थल को कार्यकर्ता की क्षमताओं के अनुरूप बनाना"], explanation: "एर्गोनॉमिक्स कार्यों, उपकरणों और कार्यस्थलों को मानव शरीर के अनुरूप अभिकल्पित करता है, जिससे दक्षता बढ़ती है और थकान तथा चोट घटती है।" },
  "s12hm-b-041": { stem: "एंजेल के नियम के अनुसार परिवार की आय बढ़ने पर भोजन पर व्यय की जाने वाली आय का प्रतिशत:", options: ["घटता है", "बढ़ता है", "स्थिर रहता है", "पहले घटता है और फिर बढ़ता है"], explanation: "भोजन पर व्यय निरपेक्ष रूप से बढ़ सकता है, पर आय बढ़ने के साथ कुल आय में इसका अंश घटता है।" },
  "s12hm-p-033": { stem: "उपभोक्ता संरक्षण अधिनियम, 2019 के अंतर्गत नव-सृजित कौन-सा निकाय अनुचित व्यापार प्रथाओं और झूठे या भ्रामक विज्ञापनों के विरुद्ध कार्रवाई कर सकता है तथा असुरक्षित वस्तुओं को वापस मँगाने का आदेश दे सकता है?", options: ["राष्ट्रीय उपभोक्ता विवाद प्रतितोष आयोग", "केंद्रीय उपभोक्ता संरक्षण प्राधिकरण", "भारतीय मानक ब्यूरो", "उपभोक्ता कल्याण कोष"], explanation: "केंद्रीय उपभोक्ता संरक्षण प्राधिकरण (CCPA) 2019 के अधिनियम के अंतर्गत स्थापित नियामक है। राष्ट्रीय आयोग पहले से विद्यमान था और उपभोक्ता विवादों का न्यायनिर्णयन करता है।" },
  "s12hm-p-034": { stem: "निम्नलिखित में से कौन-सा उपभोक्ता संरक्षण अधिनियम, 2019 में सूचीबद्ध उपभोक्ता अधिकारों में शामिल नहीं है?", options: ["सुनवाई का अधिकार", "प्रतितोष (निवारण) पाने का अधिकार", "स्वस्थ पर्यावरण का अधिकार", "उपभोक्ता जागरूकता का अधिकार"], explanation: "अधिनियम छह अधिकार सूचीबद्ध करता है: खतरनाक वस्तुओं से संरक्षण, सूचना पाने का, विकल्पों तक पहुँच के आश्वासन का, सुनवाई का, प्रतितोष पाने का और उपभोक्ता जागरूकता का। स्वस्थ पर्यावरण UN दिशानिर्देशों में है, अधिनियम की सूची में नहीं।" },
  "s12hm-p-035": { stem: "अभिकथन (A): स्पष्ट थकान आने से पहले दिए गए छोटे विश्राम-काल किसी कार्य-अवधि के कुल उत्पादन को बढ़ा सकते हैं। कारण (R): थकान पूर्णतः मनोवैज्ञानिक है और इसका कोई शरीरक्रियात्मक आधार नहीं है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "उचित समय पर विश्राम थकान को टालता है और उत्पादन बढ़ाता है, अतः A सत्य है। थकान के शरीरक्रियात्मक (जैसे पेशीय थकान) और मनोवैज्ञानिक दोनों घटक होते हैं, अतः R असत्य है।" },
  "s12hm-p-036": { stem: "रसोई नियोजन में 'कार्य त्रिभुज' किन तीन कार्य केंद्रों को जोड़ता है?", options: ["सिंक, चूल्हा (कुकिंग रेंज) और रेफ्रिजरेटर", "भोजन मेज़, सिंक और भंडार", "चूल्हा, भोजन मेज़ और द्वार", "खिड़की, सिंक और भंडार"], explanation: "कार्य त्रिभुज सिंक (सफ़ाई), चूल्हा (पकाना) और रेफ्रिजरेटर (भंडारण) केंद्रों को जोड़ता है; इसे सुगठित रखने से चलना-फिरना और ऊर्जा व्यय घटता है।" },
  "s12hm-p-037": { stem: "श्रमदक्षता सिद्धांतों के अनुसार आटा गूँधने जैसे खड़े होकर किए जाने वाले कार्य की कार्य-सतह आदर्श रूप से होनी चाहिए:", options: ["कंधे की ऊँचाई से काफ़ी ऊपर", "कार्यकर्ता की कोहनी की ऊँचाई से थोड़ी नीचे", "आँखों के स्तर पर", "घुटनों की ऊँचाई पर"], explanation: "कोहनी से थोड़ी नीची सतह पर कार्यकर्ता शिथिल, सीधी मुद्रा में बल लगा सकता है। बहुत ऊँची या नीची सतह से कंधे या पीठ पर तनाव पड़ता है।" },
  "s12hm-p-038": { stem: "परिवार को अपनी मौद्रिक आय और वास्तविक आय के उपयोग से मिलने वाली संतुष्टि कहलाती है:", options: ["मौद्रिक आय", "वास्तविक आय", "मानसिक (साइकिक) आय", "प्रयोज्य आय"], explanation: "मानसिक आय धन और वास्तविक आय के उपयोग से प्राप्त संतुष्टि है। वास्तविक आय परिवार को उपलब्ध वस्तुओं और सेवाओं का प्रवाह है।" },
  "s12hm-p-039": { stem: "समय प्रबंधन के पदों (सूची I) का उनके अर्थों (सूची II) से मिलान कीजिए। सूची I: A. पीक लोड (अधिकतम भार), B. कार्य वक्र, C. समय मानक, D. डवटेलिंग। सूची II: 1. दो या अधिक गतिविधियों को एक साथ करना या उन्हें परस्पर जोड़ना, 2. वह अवधि जब कार्य का सबसे अधिक भार पड़ता है, 3. कार्य-समय के साथ उत्पादन का आलेख जो थकान का प्रभाव दर्शाता है, 4. किसी कार्य के लिए आवश्यक मानक समय।", options: ["A-3, B-2, C-4, D-1", "A-2, B-3, C-1, D-4", "A-1, B-3, C-4, D-2", "A-2, B-3, C-4, D-1"], explanation: "पीक लोड सबसे व्यस्त अवधि है, कार्य वक्र समय के साथ उत्पादन दर्शाता है, समय मानक किसी कार्य का मानक समय है और डवटेलिंग समय बचाने हेतु गतिविधियों को परस्पर जोड़ना है।" },
  "s12hm-b-042": { stem: "संप्रेषण का SMCR (स्रोत, संदेश, माध्यम, प्राप्तकर्ता) मॉडल किसने दिया?", options: ["डेविड बर्लो", "शैनन और वीवर", "हैरोल्ड लासवेल", "अरस्तू"], explanation: "डेविड बर्लो ने 1960 में SMCR मॉडल प्रस्तुत किया, जिसमें स्रोत और प्राप्तकर्ता के कौशल, अभिवृत्ति, ज्ञान और संस्कृति जैसे कारकों पर बल दिया गया।" },
  "s12hm-b-043": { stem: "'शोर' की अवधारणा, अर्थात् प्रेषक और प्राप्तकर्ता के बीच संकेत को विकृत करने वाला कोई भी व्यवधान, किसके संप्रेषण मॉडल की केंद्रीय विशेषता है?", options: ["अरस्तू", "शैनन और वीवर", "डेविड बर्लो", "हैरोल्ड लासवेल"], explanation: "शैनन और वीवर के गणितीय मॉडल (1949) ने माध्यम में विकृति के स्रोत के रूप में शोर की अवधारणा दी।" },
  "s12hm-b-044": { stem: "'कौन, क्या, किस माध्यम से, किससे, किस प्रभाव के साथ कहता है?' संप्रेषण का यह शाब्दिक मॉडल किसने दिया?", options: ["विल्बर श्रैम", "एवरेट रोजर्स", "हैरोल्ड लासवेल", "कर्ट लेविन"], explanation: "हैरोल्ड लासवेल का सूत्र (1948) संप्रेषक, संदेश, माध्यम, श्रोता और प्रभाव की पहचान करता है।" },
  "s12hm-b-045": { stem: "किसी परिवार को गृह-वाटिका पर सलाह देने हेतु प्रसार कार्यकर्ता का गृह-भ्रमण किसका उदाहरण है?", options: ["जन (मास) विधि", "समूह विधि", "लोक माध्यम विधि", "व्यक्तिगत संपर्क विधि"], explanation: "खेत और गृह भ्रमण, व्यक्तिगत पत्र और कार्यालय भेंट व्यक्तिगत संपर्क विधियाँ हैं। बैठकें और प्रदर्शन समूह विधियाँ हैं; रेडियो और टेलीविज़न जन विधियाँ हैं।" },
  "s12hm-b-046": { stem: "एक प्रसार कार्यकर्ता माताओं को चरणबद्ध रूप से दिखाती है कि घर पर ओआरएस घोल कैसे बनाया जाए। यह शिक्षण विधि है:", options: ["विधि प्रदर्शन", "परिणाम प्रदर्शन", "प्रदर्शनी", "अभियान"], explanation: "विधि प्रदर्शन सिखाता है कि कोई कार्य कैसे करें। परिणाम प्रदर्शन किसी प्रथा का परिणाम दिखाता है, प्रायः लंबी अवधि में।" },
  "s12hm-b-047": { stem: "समेकित बाल विकास सेवा (ICDS) योजना भारत में कब आरंभ हुई?", options: ["1965", "1975", "1985", "1995"], explanation: "पोषण, स्वास्थ्य और पूर्व-विद्यालयी सेवाओं का समेकित पैकेज देने हेतु ICDS 2 अक्टूबर 1975 को आरंभ हुई।" },
  "s12hm-b-048": { stem: "ग्राम स्तर पर ICDS सेवाएँ मुख्यतः किसके माध्यम से प्रदान की जाती हैं?", options: ["केवल प्राथमिक विद्यालय", "पंचायत कार्यालय", "आँगनवाड़ी केंद्र", "उचित मूल्य की दुकानें"], explanation: "आँगनवाड़ी कार्यकर्ता और सहायिका द्वारा संचालित आँगनवाड़ी केंद्र ICDS का ज़मीनी वितरण बिंदु है।" },
  "s12hm-b-049": { stem: "मध्याह्न भोजन योजना 1995 में केंद्र प्रायोजित योजना के रूप में किस नाम से आरंभ हुई?", options: ["समेकित बाल विकास सेवा", "सर्व शिक्षा अभियान", "पोषण अभियान", "प्राथमिक शिक्षा के लिए पोषण सहायता का राष्ट्रीय कार्यक्रम"], explanation: "यह 15 अगस्त 1995 को प्राथमिक शिक्षा के लिए पोषण सहायता के राष्ट्रीय कार्यक्रम के रूप में आरंभ हुई; 2021 में इसका नाम पीएम पोषण कर दिया गया।" },
  "s12hm-b-050": { stem: "जन-सहभागिता द्वारा ग्रामीण क्षेत्रों के सर्वांगीण विकास हेतु सामुदायिक विकास कार्यक्रम भारत में कब आरंभ हुआ?", options: ["1952", "1947", "1959", "1969"], explanation: "सामुदायिक विकास कार्यक्रम 2 अक्टूबर 1952 को आरंभ हुआ। बलवंत राय मेहता समिति के बाद 1959 से पंचायती राज संस्थाएँ लागू हुईं।" },
  "s12hm-b-051": { stem: "एडगर डेल के 'अनुभव शंकु' में शंकु के आधार पर रखे गए सबसे मूर्त अधिगम अनुभव हैं:", options: ["शाब्दिक प्रतीक", "प्रत्यक्ष, उद्देश्यपूर्ण अनुभव", "चलचित्र", "प्रदर्श वस्तुएँ"], explanation: "शंकु आधार पर प्रत्यक्ष, उद्देश्यपूर्ण अनुभवों से शीर्ष पर सबसे अमूर्त शाब्दिक प्रतीकों की ओर बढ़ता है।" },
  "s12hm-p-040": { stem: "रोजर्स के नवाचार प्रसरण में वह अंगीकारकर्ता वर्ग जो लगभग 13.5% अंगीकारकर्ता बनाता है और अधिकांश सामाजिक व्यवस्थाओं में सबसे अधिक मत-नेतृत्व दर्शाता है:", options: ["नवप्रवर्तक", "प्रारंभिक बहुसंख्यक", "प्रारंभिक अंगीकारकर्ता", "पिछड़े (लैगार्ड्स)"], explanation: "प्रारंभिक अंगीकारकर्ता (लगभग 13.5%) सम्मानित स्थानीय मत-नेता होते हैं। नवप्रवर्तक (लगभग 2.5%) साहसी होते हैं पर प्रायः बाहरी माने जाते हैं; प्रारंभिक बहुसंख्यक लगभग 34% होते हैं।" },
  "s12hm-p-041": { stem: "रोजर्स (1962) द्वारा वर्णित शास्त्रीय अंगीकरण प्रक्रिया के चरणों का सही क्रम है:", options: ["रुचि, जागरूकता, परीक्षण, मूल्यांकन, अंगीकरण", "जागरूकता, मूल्यांकन, रुचि, परीक्षण, अंगीकरण", "परीक्षण, जागरूकता, रुचि, मूल्यांकन, अंगीकरण", "जागरूकता, रुचि, मूल्यांकन, परीक्षण, अंगीकरण"], explanation: "व्यक्ति पहले किसी विचार से अवगत होता है, रुचि विकसित करता है, मन में उसका मूल्यांकन करता है, छोटे पैमाने पर परीक्षण करता है और फिर उसे अपनाता है।" },
  "s12hm-p-042": { stem: "सामुदायिक विकास कार्यक्रम की समीक्षा हेतु गठित बलवंत राय मेहता समिति (1957) ने क्या अनुशंसा की?", options: ["पंचायती राज की त्रि-स्तरीय व्यवस्था", "पंचायतों की द्वि-स्तरीय व्यवस्था", "बैंकों का राष्ट्रीयकरण", "प्रखंड स्तरीय प्रशासन की समाप्ति"], explanation: "समिति ने ग्राम, प्रखंड और ज़िला स्तर पर त्रि-स्तरीय ढाँचे द्वारा 'लोकतांत्रिक विकेंद्रीकरण' की अनुशंसा की। द्वि-स्तरीय व्यवस्था बाद में अशोक मेहता समिति (1978) ने प्रस्तावित की।" },
  "s12hm-p-043": { stem: "ICDS के संबंध में कथनों पर विचार कीजिए: I. पूर्व-विद्यालयी अनौपचारिक शिक्षा 3–6 वर्ष के बच्चों के लिए है। II. पूरक पोषण छह वर्ष से कम आयु के बच्चों के साथ-साथ गर्भवती महिलाओं और धात्री माताओं को भी दिया जाता है। III. टीकाकरण, स्वास्थ्य जाँच और संदर्भन सेवाएँ सार्वजनिक स्वास्थ्य व्यवस्था के अभिसरण से दी जाती हैं। कौन-सा/से सही है/हैं?", options: ["केवल I और II", "I, II और III", "केवल II और III", "केवल I और III"], explanation: "तीनों सही हैं। ICDS की छह सेवाओं में से टीकाकरण, स्वास्थ्य जाँच और संदर्भन स्वास्थ्य व्यवस्था के माध्यम से दी जाती हैं, जबकि शेष आँगनवाड़ी केंद्रों से।" },
  "s12hm-p-044": { stem: "अभिकथन (A): प्रसार कार्यक्रमों का आरंभ लोगों की अनुभूत आवश्यकताओं से होना चाहिए। कारण (R): जब कार्यक्रम उन समस्याओं को संबोधित करता है जिन्हें लोग स्वयं पहचानते हैं, तो वे अधिक तत्परता से भाग लेते हैं और परिवर्तन को बनाए रखते हैं।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है", "A सत्य है परंतु R असत्य है", "A असत्य है परंतु R सत्य है"], explanation: "अनुभूत आवश्यकताओं से आरंभ करना प्रसार का मूल सिद्धांत है क्योंकि इससे स्वैच्छिक सहभागिता सुनिश्चित होती है, जो ठीक R का कथन है।" },
  "s12hm-p-045": { stem: "निम्नलिखित में से कौन-सा प्रक्षेपित दृश्य साधन है?", options: ["फलालैन बोर्ड (फ्लैनेल ग्राफ)", "फ्लैश कार्ड", "पोस्टर", "ओवरहेड ट्रांसपेरेंसी"], explanation: "ट्रांसपेरेंसी, स्लाइड और फ़िल्मस्ट्रिप के लिए प्रोजेक्टर चाहिए। फ्लैनेल ग्राफ, फ्लैश कार्ड और पोस्टर अप्रक्षेपित साधन हैं।" },
  "s12hm-p-046": { stem: "यह विचार कि संप्रेषण उसी सीमा तक सफल होता है जहाँ तक प्रेषक और प्राप्तकर्ता के 'अनुभव क्षेत्र' परस्पर व्याप्त होते हैं, सबसे अधिक किससे जुड़ा है?", options: ["विल्बर श्रैम", "हैरोल्ड लासवेल", "डेविड बर्लो", "अरस्तू"], explanation: "श्रैम का मॉडल कूटकर्ता और विकूटकर्ता के अनुभव क्षेत्रों को परस्पर व्याप्त वृत्तों के रूप में दिखाता है; साझा अनुभव से साझा अर्थ संभव होता है।" },
  "s12hm-p-047": { stem: "ग्रामीणों द्वारा स्वयं बनाए गए ट्रांसेक्ट वॉक, सामाजिक मानचित्रण, मौसमी कैलेंडर और वेन आरेख किसके उपकरण हैं?", options: ["जनसंचार अभियान", "सहभागी ग्रामीण मूल्यांकन (PRA)", "व्याख्यान विधि", "परिणाम प्रदर्शन"], explanation: "रॉबर्ट चैम्बर्स से संबद्ध सहभागी ग्रामीण मूल्यांकन (PRA) ऐसे दृश्य उपकरणों का प्रयोग करता है ताकि समुदाय अपनी स्थिति का स्वयं विश्लेषण करें।" },
  "s12hm-p-048": { stem: "मध्याह्न भोजन (अब पीएम पोषण) के पोषण मानकों के अंतर्गत प्राथमिक स्तर के बच्चे के पके भोजन से कितना मिलना अपेक्षित है?", options: ["700 kcal और 20 g प्रोटीन", "300 kcal और 8–12 g प्रोटीन", "450 kcal और 12 g प्रोटीन", "600 kcal और 18 g प्रोटीन"], explanation: "प्राथमिक स्तर का मानक 450 kcal और 12 g प्रोटीन है; उच्च प्राथमिक का मानक 700 kcal और 20 g प्रोटीन है। 300 kcal और 8–12 g एक पूर्ववर्ती (2004) मानक था।" },
  "s12hm-p-049": { stem: "गाँव की महिलाएँ उस प्रसार कार्यकर्ता की बात नहीं समझ पातीं जो बार-बार तकनीकी शब्द 'पोषक घनत्व' का प्रयोग करती है। यहाँ संप्रेषण की बाधा मुख्यतः है:", options: ["भौतिक बाधा", "शरीरक्रियात्मक बाधा", "यांत्रिक शोर", "अर्थगत (सिमैंटिक) बाधा"], explanation: "अर्थगत बाधाएँ उन शब्दों या प्रतीकों से उत्पन्न होती हैं जिन्हें प्राप्तकर्ता प्रेषक के अर्थ में नहीं समझता, जैसे अपरिचित तकनीकी शब्दावली।" },
};
